import type { Metadata } from "next";
import { profile } from "@/content";
import { alternatesFor, locales, ogLocales, type Locale } from "./config";

/**
 * Canonical, hreflang, Open Graph, and X/Twitter tags for one page. The share
 * image is generated by app/[locale]/opengraph-image.tsx; it's referenced
 * explicitly because a page's own `openGraph` replaces the inherited one.
 */
export function pageMetadata(
  locale: Locale,
  { path = "", title, description }: { path?: string; title: string; description: string },
): Metadata {
  const image = {
    url: `/${locale}/opengraph-image/card`,
    width: 1200,
    height: 630,
    alt: title,
  };

  return {
    alternates: alternatesFor(locale, path),
    openGraph: {
      type: path ? "website" : "profile",
      locale: ogLocales[locale],
      alternateLocale: locales.filter((l) => l !== locale).map((l) => ogLocales[l]),
      url: `/${locale}${path}`,
      siteName: profile.name,
      title,
      description,
      images: [image],
      ...(path ? {} : { firstName: profile.name.split(" ")[0], lastName: profile.name.split(" ").slice(1).join(" ") }),
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [image],
    },
  };
}
